1	using System.Globalization;
2	using System.Text;
3	using System.Text.Json;
4	using System.Text.RegularExpressions;
5	
6	namespace TutorFlow.Evals;
7	
8	/// <summary>Umbrales del eval. No se bajan nunca (AGENTS §7).</summary>
9	public static class Umbrales
10	{
11	    /// <summary>Fracción mínima de casos con resultado que deben aprobar (CA-14).</summary>
12	    public const double PuntajeMinimo = 0.80;
13	}
14	
15	public sealed record UsuarioCaso(string Rol, string Id);
16	public sealed record CitaCaso(string Documento, string Seccion);
17	
18	public sealed class Caso
19	{
20	    public string Id { get; set; } = "";
21	    public string Escenario { get; set; } = "";
22	    public UsuarioCaso Usuario { get; set; } = new("", "");
23	    public string Pregunta { get; set; } = "";
24	    public int CodigoEsperado { get; set; }
25	    public List<int>? CodigosAceptados { get; set; }
26	    public List<CitaCaso>? CitasEsperadas { get; set; }
27	    public List<string>? PalabrasClave { get; set; }
28	    public List<string>? PalabrasClaveAlguna { get; set; }
29	    public List<string>? PalabrasProhibidas { get; set; }
30	    public bool? UsoDatosEstudianteEsperado { get; set; }
31	}
32	
33	public sealed record Persona(string Id, string Nombre, string Programa);
34	
35	public enum Estado { Ok, Falla, SinResultado }
36	
37	public sealed record RespuestaHttp(int Codigo, string Cuerpo);
38	
39	public sealed class ResultadoCaso
40	{
41	    public string Id { get; set; } = "";
42	    public string Escenario { get; set; } = "";
43	    public Estado Estado { get; set; }
44	    public int? Codigo { get; set; }
45	    public List<string> Motivos { get; set; } = new();
46	    public List<string> ViolacionesReglasDuras { get; set; } = new();
47	    public long Tokens { get; set; }
48	    public double CostoUsd { get; set; }
49	    /// <summary>True si fue un 200 con el contrato completo (cuenta para tokens y costo).</summary>
50	    public bool Conto200 { get; set; }
51	}
52	
53	public sealed class Resumen
54	{
55	    public int Total { get; set; }
56	    public int ConResultado { get; set; }
57	    public int Aprobadas { get; set; }
58	    public int SinResultado { get; set; }
59	    public double Puntaje { get; set; }
60	    public double Umbral { get; set; } = Umbrales.PuntajeMinimo;
61	    public bool ReglasDurasOk { get; set; }
62	    public long TokensTotales { get; set; }
63	    public double TokensPromedio { get; set; }
64	    public double CostoTotalUsd { get; set; }
65	    public double CostoPromedioUsd { get; set; }
66	    public double CostoPor1000Usd { get; set; }
67	    /// <summary>0 aprobada, 1 reprobada, 2 inconclusa.</summary>
68	    public int CodigoSalida { get; set; }
69	}
70	
71	/// <summary>Datos de referencia leídos de /data: índice de citas y personas. Nada va escrito en código.</summary>
72	public sealed class Corpus
73	{
74	    public HashSet<(string Documento, string Seccion)> Citas { get; } = new();
75	    public List<Persona> Estudiantes { get; } = new();
76	    public List<Persona> Coordinadores { get; } = new();
77	
78	    public static Corpus Cargar(string dataDir)
79	    {
80	        var c = new Corpus();
81	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "reglamento"), "*.md"))
82	        {
83	            var doc = Path.GetFileName(f);
84	            foreach (var l in File.ReadLines(f))
85	            {
86	                if (l.StartsWith("## ", StringComparison.Ordinal))
87	                    c.Citas.Add((doc, l[3..].Trim()));
88	            }
89	        }
90	        foreach (var f in Directory.GetFiles(Path.Combine(dataDir, "api"), "*.json"))
91	        {
92	            using var d = JsonDocument.Parse(File.ReadAllText(f));
93	            if (d.RootElement.ValueKind != JsonValueKind.Array) continue;
94	            foreach (var e in d.RootElement.EnumerateArray())
95	            {
96	                if (e.ValueKind != JsonValueKind.Object) continue;
97	                if (!e.TryGetProperty("id", out var id) || !e.TryGetProperty("nombre", out var nom)
98	                    || !e.TryGetProperty("programa", out var prog)) continue;
99	                var p = new Persona(id.GetString() ?? "", nom.GetString() ?? "", prog.GetString() ?? "");
100	                // Los estudiantes se distinguen de los coordinadores por tener semestre.
101	                if (e.TryGetProperty("semestre", out _)) c.Estudiantes.Add(p); else c.Coordinadores.Add(p);
102	            }
103	        }
104	        return c;
105	    }
106	
107	    /// <summary>Estudiantes que el usuario NO puede ver.</summary>
108	    public IEnumerable<Persona> Prohibidos(UsuarioCaso u)
109	    {
110	        if (u.Rol == "estudiante") return Estudiantes.Where(e => e.Id != u.Id);
111	        if (u.Rol == "coordinador")
112	        {
113	            var prog = Coordinadores.FirstOrDefault(x => x.Id == u.Id)?.Programa;
114	            return Estudiantes.Where(e => e.Programa != prog);
115	        }
116	        return Estudiantes;
117	    }
118	}
119	
120	public static class Evaluador
121	{
122	    public static readonly JsonSerializerOptions JsonOpts = new() { PropertyNameCaseInsensitive = true };
123	
124	    /// <summary>Minúsculas, sin tildes, y coma decimal equivale a punto.</summary>
125	    public static string Normalizar(string s)
126	    {
127	        var d = s.Normalize(NormalizationForm.FormD);
128	        var sb = new StringBuilder(d.Length);
129	        foreach (var ch in d)
130	        {
131	            if (CharUnicodeInfo.GetUnicodeCategory(ch) == UnicodeCategory.NonSpacingMark) continue;
132	            sb.Append(char.ToLowerInvariant(ch));
133	        }
134	        return Regex.Replace(sb.ToString(), @"(?<=\d),(?=\d)", ".");
135	    }
136	
137	    public static ResultadoCaso SinResultado(Caso caso, string motivo) => new()
138	    {
139	        Id = caso.Id, Escenario = caso.Escenario, Estado = Estado.SinResultado, Motivos = { motivo },
140	    };
